'use strict';
// Shared helpers for the vault tools: find notes, read frontmatter, build the session index.
const fs = require('fs');
const path = require('path');

const ROOT = process.env.TIFOXR_VAULT ? path.resolve(process.env.TIFOXR_VAULT) : path.resolve(__dirname, '..', '..');

// Folders that hold tooling or generated files, not notes.
const EXEMPT_DIRS = ['.git', 'node_modules', 'tools', 'hooks', 'skills', '.claude-plugin', '.githooks', '.obsidian', '99-Templates', '05-Database/Procedures', '05-Database/_state', '_proposals'];
const CATEGORIES = ['project', 'architecture', 'decisions', 'tasks', 'database', 'conventions'];
const STATUSES = ['live', 'accepted', 'draft', 'planned', 'in-development', 'deprecated', 'archived', 'pending'];
const CATEGORY_LABEL = { project: 'project', architecture: 'architecture', decisions: 'decisions', tasks: 'tasks', database: 'database', conventions: 'conventions' };

const MAX_EAGER = 8;
const MAX_INDEX_CHARS = 4000;

const rel = (f) => path.relative(ROOT, f).replace(/\\/g, '/');
function isExempt(relPath) {
  return EXEMPT_DIRS.some((d) => relPath === d || relPath.startsWith(d + '/'));
}

function walk(dir, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    const r = rel(p);
    if (e.isDirectory()) {
      if (e.name === '.git' || e.name === 'node_modules') continue;
      walk(p, out);
    } else out.push(r);
  }
  return out;
}

// All files in the vault, relative paths with forward slashes.
function allFiles() { return walk(ROOT, []); }

function parseFrontmatter(text) {
  const t = text.replace(/\r\n/g, '\n');
  const m = t.match(/^---\n([\s\S]*?)\n---\n/);
  if (!m) return null;
  const fm = {};
  for (const line of m[1].split('\n')) {
    const k = line.match(/^([A-Za-z_][A-Za-z0-9_-]*):\s*(.*)$/);
    if (!k) continue;
    let v = k[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    fm[k[1]] = v;
  }
  return { fm, body: t.slice(m[0].length), raw: m[1] };
}

// Notes that follow the vault schema (markdown outside the exempt folders, except the generated index).
function loadNotes() {
  const notes = [];
  for (const r of allFiles()) {
    if (!r.endsWith('.md') || r === 'vault-index.md' || isExempt(r)) continue;
    const text = fs.readFileSync(path.join(ROOT, r), 'utf8');
    const p = parseFrontmatter(text);
    notes.push({ path: r, name: path.basename(r, '.md'), text, fm: p ? p.fm : null, body: p ? p.body : text });
  }
  return notes;
}

function buildIndex(notes) {
  const active = notes.filter((n) => n.fm && n.fm.status !== 'archived' && n.fm.status !== 'deprecated');
  const eager = active.filter((n) => n.fm.index_tier === 'eager')
    .sort((a, b) => CATEGORIES.indexOf(a.fm.category) - CATEGORIES.indexOf(b.fm.category) || a.name.localeCompare(b.name));
  const lazy = active.filter((n) => n.fm.index_tier !== 'eager');
  let o = '# TifoXR vault index\n\nGenerated by tools/build-index.js. Do not edit by hand.\n\n';
  o += '## Read these when the task matches\n';
  for (const n of eager) o += `- ${n.fm.title} (${n.path}): ${n.fm.agent_hint}\n`;
  o += '\n## Other notes (read only when needed)\n';
  for (const c of CATEGORIES) {
    const list = lazy.filter((n) => n.fm.category === c).sort((a, b) => a.name.localeCompare(b.name));
    if (!list.length) continue;
    if (c === 'database') {
      o += `- database: ${list.length} notes about the dev database. Start at "DB Current State" (05-Database/DB Current State.md), only for database work.\n`;
    } else {
      o += `- ${CATEGORY_LABEL[c]}: ${list.map((n) => n.fm.title).join(', ')}\n`;
    }
  }
  return o;
}

module.exports = { ROOT, EXEMPT_DIRS, CATEGORIES, STATUSES, MAX_EAGER, MAX_INDEX_CHARS, rel, isExempt, allFiles, parseFrontmatter, loadNotes, buildIndex };
